import{_ as n,o as s,c as e,a2 as p}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse('{"title":"整体架构与关键数据流","description":"从进程、共享包、存储和任务生命周期理解 Ershu 五个模块怎样协作。","frontmatter":{"page_id":"development-architecture","title":"整体架构与关键数据流","description":"从进程、共享包、存储和任务生命周期理解 Ershu 五个模块怎样协作。"},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md","lastUpdated":1786290726000}'),r={name:"development/architecture.md"};function l(t,a,i,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="整体架构与关键数据流" tabindex="-1">整体架构与关键数据流 <a class="header-anchor" href="#整体架构与关键数据流" aria-label="Permalink to &quot;整体架构与关键数据流&quot;">​</a></h1><p>Ershu 由四个运行进程和一个共享包组成。Core 会安装进 API、Worker 和 MCP 的环境中，它本身不监听端口。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ──HTTP/SSE──&gt; Frontend ──HTTP/SSE──&gt; API ─┐</span></span>
<span class="line"><span>                                                   │</span></span>
<span class="line"><span>MCP 客户端 ──Streamable HTTP──&gt; MCP ───────────────┤</span></span>
<span class="line"><span>                                                   │  调用共享 Core 服务</span></span>
<span class="line"><span>                         Worker ────────────────────┤</span></span>
<span class="line"><span>                                                   ▼</span></span>
<span class="line"><span>                                 PostgreSQL   Milvus   Redis</span></span>
<span class="line"><span>                                      │          │       │</span></span>
<span class="line"><span>                                      └── 持久结果 ┘       └── 短期协调</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                         Worker ──只读工作区──&gt; GitHub / GitLab / 本地仓库</span></span>
<span class="line"><span>                         Worker ──模型通道────&gt; 已配置的模型服务</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>图中的 Core 不是网络跳转。API、Worker 和 MCP 在自己的进程中直接导入 Core 的模型、权限和查询服务。</p><h2 id="五个模块的边界" tabindex="-1">五个模块的边界 <a class="header-anchor" href="#五个模块的边界" aria-label="Permalink to &quot;五个模块的边界&quot;">​</a></h2><h3 id="core-共同事实与规则" tabindex="-1">Core：共同事实与规则 <a class="header-anchor" href="#core-共同事实与规则" aria-label="Permalink to &quot;Core：共同事实与规则&quot;">​</a></h3><p>Core 定义数据库模型、升级记录、项目权限、运行状态、仓库工作区、检索接口、模型通道与运行时设置契约。其他后端模块可以调用这些公共服务，但不能把自己的 HTTP 或后台任务逻辑反向放进 Core。</p><p>PostgreSQL 是业务事实来源：用户、项目、仓库、权限、运行队列、文档元数据和配置覆盖都在这里持久化。Milvus 保存语义检索所需的向量数据。Redis 只承担短期缓存、租约或协调职责，不能作为任务结果来源。</p><h3 id="api-面向网页的控制面" tabindex="-1">API：面向网页的控制面 <a class="header-anchor" href="#api-面向网页的控制面" aria-label="Permalink to &quot;API：面向网页的控制面&quot;">​</a></h3><p>API 暴露 FastAPI 路由，负责 OPAQUE 登录、会话 Cookie、CSRF、项目和仓库管理、模型通道、运行创建与恢复、文档、搜索、关系查询和管理操作。</p><p>创建运行时，API 校验项目权限、分析类型、仓库范围和基线条件，再通过 Core 写入运行与队列记录。它不会在请求进程中分析代码。<code>ershu-api-poller</code> 是同仓库的独立进程，用租约协调定时仓库检查。</p><h3 id="worker-执行分析的数据面" tabindex="-1">Worker：执行分析的数据面 <a class="header-anchor" href="#worker-执行分析的数据面" aria-label="Permalink to &quot;Worker：执行分析的数据面&quot;">​</a></h3><p>Worker 领取持久队列中的可用任务，为目标提交准备受限工作区，然后按阶段建立仓库树、代码索引、知识关系、搜索索引和项目文档。它持续写入阶段、检查点、事件、用量与最终结果，使 API 可以在连接中断后恢复读取。</p><p>只读仓库工具会限制路径、文件大小和调用预算，也不会执行仓库脚本。语言服务运行在受控环境中；当前支持的语言能力和依赖准备不是同一概念，例如 Java 语言服务存在，但不会自动执行 Maven 依赖准备。</p><h3 id="mcp-面向开发智能体的只读面" tabindex="-1">MCP：面向开发智能体的只读面 <a class="header-anchor" href="#mcp-面向开发智能体的只读面" aria-label="Permalink to &quot;MCP：面向开发智能体的只读面&quot;">​</a></h3><p>MCP 通过 Streamable HTTP 提供项目解析、文档、树、代码索引、关系、搜索和上下文查询工具。请求先验证 Bearer 凭据，再按密钥范围和项目权限调用 Core 服务。</p><p>MCP 工具不能创建项目、修改仓库或启动运行。需要改变状态的工作应走网页或 API。当前服务器注册 27 个工具；工具数量属于本版本事实，不应被客户端写成永久常量。</p><h3 id="frontend-人的工作区" tabindex="-1">Frontend：人的工作区 <a class="header-anchor" href="#frontend-人的工作区" aria-label="Permalink to &quot;Frontend：人的工作区&quot;">​</a></h3><p>前端是 React 单页应用，通过 API 客户端调用 HTTP 与 SSE。它提供登录、项目切换、仓库和运行、文档阅读与问答、代码搜索、关系图、MCP 密钥以及系统管理页面。</p><p>页面刷新后，前端会先恢复登录状态，再从 API 读取持久运行快照；实时事件只是加快更新，不是唯一状态来源。前端不直接知道数据库或 Worker 实例。</p><h2 id="一次完整分析怎样流动" tabindex="-1">一次完整分析怎样流动？ <a class="header-anchor" href="#一次完整分析怎样流动" aria-label="Permalink to &quot;一次完整分析怎样流动？&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建请求</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ API：认证、授权、校验全项目基线和仓库范围</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Core：写入 AnalysisRun 与 RunQueueItem</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Worker：领取租约并固定目标提交</span></span>
<span class="line"><span>  │     ├─ 准备只读工作区</span></span>
<span class="line"><span>  │     ├─ 提取确定性仓库事实</span></span>
<span class="line"><span>  │     ├─ 建立代码、关系与搜索索引</span></span>
<span class="line"><span>  │     └─ 通过模型通道生成项目文档</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Core：持续保存阶段、事件、检查点、用量和结果</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ API / Frontend：读取最终状态；MCP：读取已发布结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>任务以队列记录为恢复边界。Worker 通过租约避免同一任务被多个实例同时执行；实例失联后，符合恢复条件的任务可以重新进入可领取状态。调用方必须根据最终状态判断成功，不能把 HTTP 创建成功当成分析成功。</p><h2 id="增量分析怎样保持项目视图" tabindex="-1">增量分析怎样保持项目视图？ <a class="header-anchor" href="#增量分析怎样保持项目视图" aria-label="Permalink to &quot;增量分析怎样保持项目视图？&quot;">​</a></h2><p>首次 <code>full_project</code> 运行会固定所有有效仓库的提交，建立项目基线。后续增量运行只处理发生变化的仓库和提交，但输出仍属于项目级视图。API 会拒绝缺少基线的增量请求。</p><p>Cron 轮询和 Webhook 都先解析仓库变化，再创建普通运行。Webhook 签名验证使用时间戳、空字节、随机数、空字节和原始请求体拼接的数据；任何代理或中间件都不应先重写请求体。</p><h2 id="读取结果的三条路径" tabindex="-1">读取结果的三条路径 <a class="header-anchor" href="#读取结果的三条路径" aria-label="Permalink to &quot;读取结果的三条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>适合的使用者</th><th>特点</th></tr></thead><tbody><tr><td>前端</td><td>团队成员和管理员</td><td>完整管理、可视化和交互式跟踪</td></tr><tr><td>API</td><td>自动化与前端开发</td><td>可以改变状态，也提供快照和查询接口</td></tr><tr><td>MCP</td><td>开发智能体</td><td>只读、项目范围、返回可继续核对的来源</td></tr></tbody></table><p>修改架构时，优先保持这三条边界：状态改变留在 API，长任务留在 Worker，共享数据和规则留在 Core，智能体查询留在 MCP，人的交互留在前端。</p><blockquote><p>事实来源：各模块入口、依赖清单、导入边界测试、运行队列模型、Worker 分析阶段、MCP 工具注册表和前端路由。</p></blockquote>`,30)])])}const u=n(r,[["render",l]]);export{h as __pageData,u as default};
